\documentclass[border = 5mm]{standalone}
\usepackage[dvipsnames]{xcolor}
\usepackage{tikz}
\usetikzlibrary{shapes,shadows,arrows}
\usepackage{tkz-euclide}
%\usetkzobj{all}

\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

\begin{document}
\pagestyle{empty}
\begin{tikzpicture}[scale=1.0, every node/.style={transform shape}]

\def\mycolor{deepskyblue}
\def\mycolorsecondary{fadedpink}
\def\myarrowcolor{gray!70!black}
\def\myfillopacity{0.25}

\def\w{5}
\def\h{4}

%%% Polygon
\node[draw=none, fill=none] at (0,0) {$A \Rightarrow B$}; 
\node[above=5pt, \mycolor!80!black] at (0,0) {\bf Statement};

\node[draw=none, fill=none] at (\w,0) {$B \Rightarrow A$}; 
\node[above=5pt, \mycolorsecondary!80!black] at (\w,0) {\bf Converse};

\node[draw=none, fill=none] at (0,-\h) {$\neg A \Rightarrow \neg B$};
\node[below=5pt, \mycolorsecondary!80!black] at (0,-\h) {\bf Inverse};

\node[draw=none, fill=none] at (\w,-\h) {$\neg B \Rightarrow \neg A$};
\node[below=5pt, \mycolor!80!black] at (\w,-\h) {\bf Contrapositive};
\node[below=16pt, \myarrowcolor] at (\w,-\h) {\small Inverse of Converse};
\node[below=27pt, \myarrowcolor] at (\w,-\h) {\small Converse of Inverse};

%%% Arrowa
\draw[< ->, thick, \myarrowcolor, shorten <  = 3mm, shorten > = 3mm] (0,0) -- (0,-\h) node[midway, left=3pt] {negate};
\draw[< ->, thick, \myarrowcolor, shorten <  = 3mm, shorten > = 3mm] (\w,0) -- (\w,-\h) node[midway, right=3pt] {negate};

\draw[< ->, thick, \myarrowcolor, shorten <  = 10mm, shorten > = 10mm] (0,0) -- (\w,0) node[midway, above=3pt] {flip};
\draw[< ->, thick, \myarrowcolor, shorten <  = 10mm, shorten > = 10mm] (0,-\h) -- (\w,-\h) node[midway, below=3pt] {flip};
%====================

% Inverse = Converse
\draw[double, double distance=5pt, \mycolorsecondary, line cap=butt, ultra thick, shorten <  = 8mm, shorten > = 8mm] (\w,0) -- (0,-\h) node[midway, above=3pt] {};
\draw[white, line cap=butt, line width=4.7pt, shorten <  = 7mm, shorten > = 7mm] (\w,0) -- (0,-\h) node[midway, above=3pt] {};

% Direct = Contrapositive
\draw[double, double distance=5pt, \mycolor, line cap=butt, ultra thick, shorten <  = 8mm, shorten > = 8mm] (0,0) -- (\w,-\h) node[midway, above=3pt] {};
\draw[white, line cap=butt, line width=4.7pt, shorten <  = 7mm, shorten > = 7mm] (0,0) -- (\w,-\h) node[midway, above=3pt] {};

\end{tikzpicture}
\end{document}

